import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONArray
import org.json.JSONObject
import java.io.IOException
import java.util.concurrent.TimeUnit

internal val http: OkHttpClient = OkHttpClient.Builder()
    .connectTimeout(15, TimeUnit.SECONDS).readTimeout(60, TimeUnit.SECONDS).writeTimeout(30, TimeUnit.SECONDS).build()
private val JSON = "application/json; charset=utf-8".toMediaType()

internal suspend fun execute(req: Request, provider: String): Pair<Int, String> = withContext(Dispatchers.IO) {
    try { http.newCall(req).execute().use { it.code to (it.body?.string() ?: "") } }
    catch (e: IOException) { throw AiException("network", "$provider network error: ${e.javaClass.simpleName}", "No internet connection or $provider is unreachable. Check your network and try again.") }
}

internal fun mapHttpError(provider: Provider, code: Int, body: String): AiException {
    val detail = runCatching { JSONObject(body).optJSONObject("error")?.optString("message") }.getOrNull().orEmpty().take(160)
    return when (code) {
        400 -> if (detail.contains("API key", true)) AiException("invalid_key", detail, "${provider.label} rejected this API key. Check it and try again.")
               else AiException("bad_request", detail, "${provider.label} could not process the request. ${detail}".trim())
        401, 403 -> AiException("invalid_key", detail, "${provider.label} rejected this API key (HTTP $code). Create a new key and paste it again.")
        404 -> AiException("model_not_found", detail, "The selected model is not available for this key. Pick another model in Settings.")
        429 -> AiException("rate_limited", detail, "${provider.label} says you are sending too many requests or your free quota is used up. Wait a bit or switch provider.")
        in 500..599 -> AiException("server_error", detail, "${provider.label} is having problems right now (HTTP $code). Try again shortly.")
        else -> AiException("http_$code", detail, "Unexpected response from ${provider.label} (HTTP $code).")
    }
}

interface AiClient {
    val provider: Provider
    /** Real call to the provider: also serves as the connection test. */
    suspend fun listModels(apiKey: String): List<String>
    suspend fun chat(apiKey: String, model: String, system: String, history: List<ChatMessage>): AiReply
}

class GeminiClient : AiClient {
    override val provider = Provider.GEMINI
    private val base = "https://generativelanguage.googleapis.com/v1beta"

    override suspend fun listModels(apiKey: String): List<String> {
        val (code, body) = execute(Request.Builder().url("$base/models?pageSize=200").header("x-goog-api-key", apiKey).build(), "Gemini")
        if (code != 200) throw mapHttpError(provider, code, body)
        val arr = JSONObject(body).optJSONArray("models") ?: JSONArray()
        return (0 until arr.length()).map { arr.getJSONObject(it) }
            .filter { m -> m.optJSONArray("supportedGenerationMethods")?.let { a -> (0 until a.length()).any { a.getString(it) == "generateContent" } } == true }
            .map { it.getString("name").removePrefix("models/") }.filter { it.startsWith("gemini") }.sortedDescending()
    }

    override suspend fun chat(apiKey: String, model: String, system: String, history: List<ChatMessage>): AiReply {
        val contents = JSONArray()
        history.forEach { m -> contents.put(JSONObject().put("role", if (m.role == "assistant") "model" else "user").put("parts", JSONArray().put(JSONObject().put("text", m.content)))) }
        val payload = JSONObject().put("contents", contents)
            .put("system_instruction", JSONObject().put("parts", JSONArray().put(JSONObject().put("text", system))))
        val t0 = System.currentTimeMillis()
        val (code, body) = execute(Request.Builder().url("$base/models/$model:generateContent").header("x-goog-api-key", apiKey).post(payload.toString().toRequestBody(JSON)).build(), "Gemini")
        if (code != 200) throw mapHttpError(provider, code, body)
        val j = JSONObject(body)
        val text = j.optJSONArray("candidates")?.optJSONObject(0)?.optJSONObject("content")?.optJSONArray("parts")?.optJSONObject(0)?.optString("text").orEmpty()
        if (text.isBlank()) {
            val why = j.optJSONObject("promptFeedback")?.optString("blockReason").orEmpty()
            throw AiException("empty_reply", "empty Gemini reply $why", if (why.isNotEmpty()) "Gemini blocked this request ($why). Try rephrasing." else "Gemini returned an empty answer. Try again.")
        }
        val u = j.optJSONObject("usageMetadata")
        return AiReply(text.trim(), provider, model, u?.optLong("promptTokenCount") ?: 0, u?.optLong("candidatesTokenCount") ?: 0, System.currentTimeMillis() - t0)
    }
}

class GroqClient : AiClient {
    override val provider = Provider.GROQ
    private val base = "https://api.groq.com/openai/v1"

    override suspend fun listModels(apiKey: String): List<String> {
        val (code, body) = execute(Request.Builder().url("$base/models").header("Authorization", "Bearer $apiKey").build(), "Groq")
        if (code != 200) throw mapHttpError(provider, code, body)
        val arr = JSONObject(body).optJSONArray("data") ?: JSONArray()
        return (0 until arr.length()).map { arr.getJSONObject(it).getString("id") }
            .filterNot { id -> listOf("whisper", "guard", "tts", "playai", "distil-whisper").any { id.contains(it, true) } }.sorted()
    }

    override suspend fun chat(apiKey: String, model: String, system: String, history: List<ChatMessage>): AiReply {
        val msgs = JSONArray().put(JSONObject().put("role", "system").put("content", system))
        history.forEach { msgs.put(JSONObject().put("role", it.role).put("content", it.content)) }
        val payload = JSONObject().put("model", model).put("messages", msgs).put("temperature", 0.7)
        val t0 = System.currentTimeMillis()
        val (code, body) = execute(Request.Builder().url("$base/chat/completions").header("Authorization", "Bearer $apiKey").post(payload.toString().toRequestBody(JSON)).build(), "Groq")
        if (code != 200) throw mapHttpError(provider, code, body)
        val j = JSONObject(body)
        val text = j.optJSONArray("choices")?.optJSONObject(0)?.optJSONObject("message")?.optString("content").orEmpty()
        if (text.isBlank()) throw AiException("empty_reply", "empty Groq reply", "Groq returned an empty answer. Try again.")
        val u = j.optJSONObject("usage")
        return AiReply(text.trim(), provider, model, u?.optLong("prompt_tokens") ?: 0, u?.optLong("completion_tokens") ?: 0, System.currentTimeMillis() - t0)
    }
}

package dev.pages.badshah222ai.data.ai

import dev.pages.badshah222ai.core.SecureStore
import dev.pages.badshah222ai.data.supabase.SupabaseApi
import dev.pages.badshah222ai.domain.*

/** Provider switching + per-user keys + usage reporting. There is NO shared developer key anywhere. */
class AiRepository(private val store: SecureStore, private val cloud: SupabaseApi) {
    private val clients = mapOf(Provider.GEMINI to GeminiClient(), Provider.GROQ to GroqClient())
    private fun client(p: Provider) = clients.getValue(p)

    fun isConfigured(p: Provider) = store.apiKey(p) != null && store.model(p) != null

    /** Tests the key with a real request and returns the models it may use. */
    suspend fun testConnection(p: Provider, key: String): List<String> {
        require(key.isNotBlank()) { "empty key" }
        val models = client(p).listModels(key.trim())
        if (models.isEmpty()) throw AiException("no_models", "no models", "The key works but no chat models are available on this account.")
        return models
    }

    suspend fun chat(history: List<ChatMessage>, personality: String = "friendly, confident and respectful"): AiReply {
        val p = store.provider
        val key = store.apiKey(p) ?: throw AiException("no_key", "no key", "Add your ${p.label} API key in Settings to start chatting.")
        val model = store.model(p) ?: throw AiException("no_model", "no model", "Test your ${p.label} key and choose a model in Settings.")
        return try {
            val reply = client(p).chat(key, model, SystemPrompt.build(personality, store.language), history.takeLast(20))
            cloud.recordUsage(p.id, model, "chat", true, reply.inputTokens, reply.outputTokens, reply.latencyMs.toInt(), null)
            reply
        } catch (e: AiException) {
            cloud.recordUsage(p.id, model, "chat", false, 0, 0, null, e.code)
            throw e
        }
    }
}

package dev.pages.badshah222ai.data.auth

import android.app.Activity
import com.google.android.libraries.identity.googleid.GetGoogleIdOption
import com.google.android.libraries.identity.googleid.GoogleIdTokenCredential
import androidx.credentials.CredentialManager
import androidx.credentials.CustomCredential
import androidx.credentials.GetCredentialRequest
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.auth.FirebaseUser
import com.google.firebase.auth.GoogleAuthProvider
import com.google.firebase.functions.FirebaseFunctions
import dev.pages.badshah222ai.core.Config
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow
import kotlinx.coroutines.tasks.await

/** Firebase Auth is the identity. The Firebase UID is the user id everywhere (Supabase `sub`). */
class AuthRepository(private val webClientId: String) {
    private val auth = FirebaseAuth.getInstance()
    val current: FirebaseUser? get() = auth.currentUser

    val userFlow: Flow<FirebaseUser?> = callbackFlow {
        val l = FirebaseAuth.AuthStateListener { trySend(it.currentUser) }
        auth.addAuthStateListener(l); awaitClose { auth.removeAuthStateListener(l) }
    }

    suspend fun signInEmail(email: String, password: String) = auth.signInWithEmailAndPassword(email.trim(), password).await().user!!
    suspend fun registerEmail(email: String, password: String) = auth.createUserWithEmailAndPassword(email.trim(), password).await().user!!
    suspend fun sendPasswordReset(email: String) { auth.sendPasswordResetEmail(email.trim()).await() }

    suspend fun signInGoogle(activity: Activity): Pair<FirebaseUser, Boolean> {
        val option = GetGoogleIdOption.Builder().setFilterByAuthorizedAccounts(false).setServerClientId(webClientId).build()
        val request = GetCredentialRequest.Builder().addCredentialOption(option).build()
        val cred = CredentialManager.create(activity).getCredential(activity, request).credential
        require(cred is CustomCredential && cred.type == GoogleIdTokenCredential.TYPE_GOOGLE_ID_TOKEN_CREDENTIAL) { "Unexpected credential type" }
        val google = GoogleIdTokenCredential.createFrom(cred.data)
        val result = auth.signInWithCredential(GoogleAuthProvider.getCredential(google.idToken, null)).await()
        return result.user!! to (result.additionalUserInfo?.isNewUser == true)
    }

    fun providerId(): String = current?.providerData?.firstOrNull { it.providerId != "firebase" }?.providerId ?: "password"
    fun signOut() = auth.signOut()

    /**
     * Returns a Firebase ID token carrying role=authenticated (needed by Supabase), or null.
     * If the claim is missing, asks the deployed `setSupabaseClaims` Cloud Function to stamp it, then refreshes.
     */
    suspend fun supabaseToken(): String? {
        val user = auth.currentUser ?: return null
        return runCatching {
            var r = user.getIdToken(false).await()
            if (r.claims["role"] != "authenticated") {
                FirebaseFunctions.getInstance(Config.FUNCTIONS_REGION).getHttpsCallable("setSupabaseClaims").call().await()
                r = user.getIdToken(true).await()
            }
            if (r.claims["role"] == "authenticated") r.token else null
        }.getOrNull()
    }
}

package dev.pages.badshah222ai.data.local

import android.content.Context
import dev.pages.badshah222ai.domain.ChatMessage
import org.json.JSONArray
import org.json.JSONObject
import java.io.File

/** Private on-device chat history (works offline / when cloud sync is unavailable). One JSON file per signed-in user. */
class ChatStore(private val context: Context) {
    private fun file(uid: String) = File(context.filesDir, "chat_${uid.filter { it.isLetterOrDigit() }}.json")

    fun load(uid: String): List<ChatMessage> = runCatching {
        val f = file(uid); if (!f.exists()) return emptyList()
        val a = JSONArray(f.readText()); (0 until a.length()).map { a.getJSONObject(it).let { o -> ChatMessage(o.getString("r"), o.getString("c"), o.optLong("t")) } }
    }.getOrDefault(emptyList())

    fun save(uid: String, msgs: List<ChatMessage>) {
        val a = JSONArray(); msgs.takeLast(300).forEach { a.put(JSONObject().put("r", it.role).put("c", it.content).put("t", it.timeMs)) }
        file(uid).writeText(a.toString())
    }
    fun clear(uid: String) { file(uid).delete() }
}

package dev.pages.badshah222ai.data.phone

import android.Manifest
import android.content.ActivityNotFoundException
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.net.Uri
import android.provider.AlarmClock
import android.provider.ContactsContract
import android.provider.MediaStore
import android.telephony.PhoneNumberUtils
import android.telephony.TelephonyManager
import androidx.core.content.ContextCompat
import dev.pages.badshah222ai.domain.PhoneAction
import java.net.URLEncoder

sealed class PhoneResult {
    data class Done(val message: String) : PhoneResult()
    data class NeedPermission(val permission: String, val why: String) : PhoneResult()
    data class Failed(val message: String) : PhoneResult()
    object LaunchContactPicker : PhoneResult()
}

/**
 * Executes assistant actions through OFFICIAL Android intents only.
 * Nothing here places a call or sends a message by itself: the dialer / SMS app / WhatsApp opens
 * pre-filled and the user presses the final button. (Callers also show a confirmation first.)
 */
class PhoneExecutor(private val ctx: Context) {
    private fun launch(i: Intent): Boolean = try { i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK); ctx.startActivity(i); true } catch (e: ActivityNotFoundException) { false } catch (e: SecurityException) { false }
    private fun launchPackage(pkg: String): Boolean = ctx.packageManager.getLaunchIntentForPackage(pkg)?.let { launch(it) } ?: false
    private fun url(u: String) = launch(Intent(Intent.ACTION_VIEW, Uri.parse(u)))
    private fun hasContacts() = ContextCompat.checkSelfPermission(ctx, Manifest.permission.READ_CONTACTS) == PackageManager.PERMISSION_GRANTED

    fun execute(a: PhoneAction): PhoneResult = when (a) {
        PhoneAction.OpenYouTube -> if (launchPackage("com.google.android.youtube") || url("https://www.youtube.com")) PhoneResult.Done("Opening YouTube.") else PhoneResult.Failed("Could not open YouTube.")
        PhoneAction.OpenWhatsApp -> if (launchPackage("com.whatsapp") || launchPackage("com.whatsapp.w4b")) PhoneResult.Done("Opening WhatsApp.") else PhoneResult.Failed("WhatsApp is not installed on this phone.")
        PhoneAction.OpenChrome -> if (launchPackage("com.android.chrome") || url("https://www.google.com")) PhoneResult.Done("Opening Chrome.") else PhoneResult.Failed("Could not open a browser.")
        PhoneAction.OpenCamera -> if (launch(Intent(MediaStore.INTENT_ACTION_STILL_IMAGE_CAMERA))) PhoneResult.Done("Opening the camera.") else PhoneResult.Failed("No camera app found.")
        PhoneAction.OpenGallery -> if (launch(Intent(Intent.ACTION_VIEW, MediaStore.Images.Media.EXTERNAL_CONTENT_URI)) || launch(Intent(Intent.ACTION_PICK, MediaStore.Images.Media.EXTERNAL_CONTENT_URI))) PhoneResult.Done("Opening your gallery.") else PhoneResult.Failed("No gallery app found.")
        PhoneAction.PickContact -> PhoneResult.LaunchContactPicker
        is PhoneAction.OpenApp -> openByName(a.appName)
        is PhoneAction.WebSearch -> if (launch(Intent(Intent.ACTION_WEB_SEARCH).putExtra("query", a.query)) || url("https://www.google.com/search?q=" + URLEncoder.encode(a.query, "UTF-8"))) PhoneResult.Done("Searching for ${a.query}.") else PhoneResult.Failed("Could not start a search.")
        is PhoneAction.SetAlarm -> if (launch(Intent(AlarmClock.ACTION_SET_ALARM).putExtra(AlarmClock.EXTRA_HOUR, a.hour24).putExtra(AlarmClock.EXTRA_MINUTES, a.minute).putExtra(AlarmClock.EXTRA_MESSAGE, a.label ?: "BADSHAH AI").putExtra(AlarmClock.EXTRA_SKIP_UI, false)))
            PhoneResult.Done("Alarm set for %02d:%02d. Confirm it in the clock app.".format(a.hour24, a.minute)) else PhoneResult.Failed("No clock app found.")
        is PhoneAction.StartTimer -> if (launch(Intent(AlarmClock.ACTION_SET_TIMER).putExtra(AlarmClock.EXTRA_LENGTH, a.seconds).putExtra(AlarmClock.EXTRA_MESSAGE, a.label ?: "BADSHAH AI").putExtra(AlarmClock.EXTRA_SKIP_UI, false)))
            PhoneResult.Done("Timer started for ${a.seconds / 60} min ${a.seconds % 60} sec.") else PhoneResult.Failed("No clock app found.")
        is PhoneAction.Call -> withNumber(a.target) { num -> if (launch(Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + Uri.encode(num))))) PhoneResult.Done("Dialer opened for $num. Press call to connect.") else PhoneResult.Failed("No dialer found.") }
        is PhoneAction.Sms -> withNumber(a.target) { num -> if (launch(Intent(Intent.ACTION_SENDTO, Uri.parse("smsto:" + Uri.encode(num))).putExtra("sms_body", a.message))) PhoneResult.Done("Message ready for $num. Press send in your messages app.") else PhoneResult.Failed("No SMS app found.") }
        is PhoneAction.WhatsAppMessage -> withNumber(a.target) { num ->
            val e164 = toE164(num) ?: return@withNumber PhoneResult.Failed("I need the number with country code (for example +92...) to open WhatsApp.")
            if (url("https://wa.me/${e164.removePrefix("+")}?text=" + URLEncoder.encode(a.message, "UTF-8"))) PhoneResult.Done("WhatsApp chat opened with your message ready. Press send.") else PhoneResult.Failed("Could not open WhatsApp.")
        }
    }

    private fun withNumber(target: String, f: (String) -> PhoneResult): PhoneResult {
        if (target.matches(Regex("^[+]?[0-9]{5,}$"))) return f(target)
        if (!hasContacts()) return PhoneResult.NeedPermission(Manifest.permission.READ_CONTACTS, "To find \"$target\" in your contacts I need permission to read contacts. Or say the phone number instead.")
        val num = findContactNumber(target) ?: return PhoneResult.Failed("I could not find \"$target\" in your contacts.")
        return f(num)
    }

    private fun findContactNumber(name: String): String? = ctx.contentResolver.query(
        ContactsContract.CommonDataKinds.Phone.CONTENT_URI,
        arrayOf(ContactsContract.CommonDataKinds.Phone.NUMBER, ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME),
        "${ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME} LIKE ?", arrayOf("%$name%"),
        "${ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME} ASC LIMIT 1")?.use { c -> if (c.moveToFirst()) c.getString(0) else null }

    private fun toE164(raw: String): String? {
        val digits = raw.filter { it.isDigit() || it == '+' }
        if (digits.startsWith("+")) return digits
        val iso = (ctx.getSystemService(Context.TELEPHONY_SERVICE) as? TelephonyManager)?.simCountryIso?.uppercase().orEmpty()
        return if (iso.isNotEmpty()) PhoneNumberUtils.formatNumberToE164(digits, iso) else null
    }

    private fun openByName(name: String): PhoneResult {
        val pm = ctx.packageManager
        val apps = pm.queryIntentActivities(Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER), 0)
            .map { it.loadLabel(pm).toString() to it.activityInfo.packageName }
        val q = name.lowercase()
        val hit = apps.firstOrNull { it.first.lowercase() == q } ?: apps.firstOrNull { it.first.lowercase().startsWith(q) } ?: apps.firstOrNull { it.first.lowercase().contains(q) }
        return if (hit != null && launchPackage(hit.second)) PhoneResult.Done("Opening ${hit.first}.") else PhoneResult.Failed("I could not find an app called \"$name\".")
    }
}

package dev.pages.badshah222ai.data.supabase

import dev.pages.badshah222ai.core.Config
import dev.pages.badshah222ai.data.ai.http
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONArray
import org.json.JSONObject
import java.io.IOException
import java.net.URLEncoder

class CloudException(message: String, val status: Int = 0) : Exception(message)

data class TicketRow(val id: String, val subject: String, val status: String, val message: String, val updatedAt: String)
data class TicketReply(val sender: String, val message: String, val createdAt: String)
data class RemoteConvo(val id: String, val title: String, val updatedAt: String)
data class RemoteMsg(val role: String, val content: String)
data class VoiceProfileRow(val id: String, val label: String, val category: String, val pitch: Float, val speed: Float, val language: String)

/**
 * Talks to Supabase PostgREST using ONLY the public publishable key plus the signed-in user's
 * Firebase ID token. Row Level Security decides what each user may read/write.
 * [token] returns a Firebase ID token that carries role=authenticated, or null when cloud sync is unavailable.
 */
class SupabaseApi(private val token: suspend () -> String?) {
    private val json = "application/json".toMediaType()

    private suspend fun call(method: String, path: String, body: String? = null, prefer: String? = null, auth: Boolean = true): String = withContext(Dispatchers.IO) {
        val jwt = if (auth) token() ?: throw CloudException("Cloud sync is not available yet (sign in again or see Help > Troubleshooting).") else null
        val rb = Request.Builder().url("${Config.SUPABASE_URL}/rest/v1/$path")
            .header("apikey", Config.SUPABASE_KEY).header("Content-Type", "application/json")
        if (jwt != null) rb.header("Authorization", "Bearer $jwt")
        if (prefer != null) rb.header("Prefer", prefer)
        rb.method(method, body?.toRequestBody(json) ?: if (method == "GET" || method == "DELETE") null else "".toRequestBody(json))
        try {
            http.newCall(rb.build()).execute().use { r ->
                val text = r.body?.string().orEmpty()
                if (!r.isSuccessful) throw CloudException(runCatching { JSONObject(text).optString("message") }.getOrNull().orEmpty().ifBlank { "Server error ${r.code}" }, r.code)
                text
            }
        } catch (e: IOException) { throw CloudException("No connection to the server.") }
    }
    private fun enc(s: String) = URLEncoder.encode(s, "UTF-8")
    private fun rows(s: String) = if (s.isBlank()) JSONArray() else JSONArray(s)

    // ---- identity / analytics (security-definer RPCs created in migration 002) ----
    /** Returns true if the account is blocked. */
    suspend fun touchProfile(email: String?, name: String?, avatar: String?): Boolean {
        val b = JSONObject().put("p_email", email ?: JSONObject.NULL).put("p_display_name", name ?: JSONObject.NULL).put("p_avatar_url", avatar ?: JSONObject.NULL)
        return JSONObject(call("POST", "rpc/app_touch_profile", b.toString())).optBoolean("is_blocked", false)
    }
    suspend fun recordLogin(provider: String, event: String) {
        runCatching { call("POST", "rpc/app_record_login", JSONObject().put("p_provider", provider).put("p_event_type", event).put("p_device", "android").toString()) }
    }
    /** Best effort: analytics must never break the chat. */
    suspend fun recordUsage(provider: String, model: String, type: String, ok: Boolean, inTok: Long, outTok: Long, latency: Int?, err: String?) {
        runCatching {
            val b = JSONObject().put("p_provider", provider).put("p_model", model).put("p_event_type", type).put("p_success", ok)
                .put("p_input_tokens", inTok).put("p_output_tokens", outTok).put("p_latency_ms", latency ?: JSONObject.NULL).put("p_error_code", err ?: JSONObject.NULL)
            call("POST", "rpc/app_record_usage", b.toString())
        }
    }

    // ---- preferences (never contains API keys) ----
    suspend fun savePreferences(userId: String, provider: String, model: String?, voice: String?, engine: String, rate: Float, pitch: Float, lang: String) {
        val b = JSONObject().put("user_id", userId).put("selected_provider", provider).put("selected_model", model ?: JSONObject.NULL)
            .put("selected_voice", voice ?: JSONObject.NULL).put("voice_engine", engine).put("speech_rate", rate.toDouble()).put("speech_pitch", pitch.toDouble()).put("language", lang)
        call("POST", "user_preferences?on_conflict=user_id", b.toString(), "resolution=merge-duplicates")
    }
    /** Stores only the STATUS of a provider (configured / tested), never the key. */
    suspend fun saveProviderStatus(userId: String, provider: String, configured: Boolean, status: String) {
        val b = JSONObject().put("user_id", userId).put("provider", provider).put("is_configured", configured).put("connection_status", status).put("last_tested_at", java.time.Instant.now().toString())
        call("POST", "user_provider_settings?on_conflict=user_id,provider", b.toString(), "resolution=merge-duplicates")
    }

    // ---- chat history ----
    suspend fun createConversation(userId: String, title: String, provider: String, model: String): String {
        val b = JSONObject().put("user_id", userId).put("title", title.take(60)).put("ai_provider", provider).put("model_name", model)
        return rows(call("POST", "conversations", b.toString(), "return=representation")).getJSONObject(0).getString("id")
    }
    suspend fun addMessage(userId: String, convoId: String, role: String, content: String, provider: String?, model: String?) {
        val b = JSONObject().put("conversation_id", convoId).put("user_id", userId).put("role", role).put("content", content).put("ai_provider", provider ?: JSONObject.NULL).put("model_name", model ?: JSONObject.NULL)
        call("POST", "messages", b.toString())
        runCatching { call("PATCH", "conversations?id=eq.${enc(convoId)}", JSONObject().put("updated_at", java.time.Instant.now().toString()).toString()) }
    }
    suspend fun listConversations(): List<RemoteConvo> = rows(call("GET", "conversations?select=id,title,updated_at&order=updated_at.desc&limit=100")).let { a -> (0 until a.length()).map { a.getJSONObject(it).let { o -> RemoteConvo(o.getString("id"), o.getString("title"), o.getString("updated_at")) } } }
    suspend fun listMessages(convoId: String): List<RemoteMsg> = rows(call("GET", "messages?select=role,content&conversation_id=eq.${enc(convoId)}&order=created_at.asc&limit=500")).let { a -> (0 until a.length()).map { a.getJSONObject(it).let { o -> RemoteMsg(o.getString("role"), o.getString("content")) } } }
    suspend fun deleteConversation(id: String) { call("DELETE", "conversations?id=eq.${enc(id)}") }

    // ---- support center ----
    suspend fun createTicket(userId: String, subject: String, category: String, message: String) {
        call("POST", "support_tickets", JSONObject().put("user_id", userId).put("subject", subject.take(150)).put("category", category).put("message", message.take(4000)).toString())
    }
    suspend fun listTickets(): List<TicketRow> = rows(call("GET", "support_tickets?select=id,subject,status,message,updated_at&order=updated_at.desc&limit=50")).let { a -> (0 until a.length()).map { a.getJSONObject(it).let { o -> TicketRow(o.getString("id"), o.getString("subject"), o.getString("status"), o.getString("message"), o.getString("updated_at")) } } }
    suspend fun ticketReplies(ticketId: String): List<TicketReply> = rows(call("GET", "support_messages?select=sender_type,message,created_at&ticket_id=eq.${enc(ticketId)}&order=created_at.asc")).let { a -> (0 until a.length()).map { a.getJSONObject(it).let { o -> TicketReply(o.getString("sender_type"), o.getString("message"), o.getString("created_at")) } } }
    suspend fun addTicketMessage(ticketId: String, message: String) { call("POST", "support_messages", JSONObject().put("ticket_id", ticketId).put("sender_type", "user").put("message", message.take(4000)).toString()) }

    // ---- remote app configuration (admin controlled) ----
    suspend fun maintenanceMessage(): String? = runCatching {
        val a = rows(call("GET", "app_config?select=config_value&config_key=eq.maintenance"))
        a.optJSONObject(0)?.optJSONObject("config_value")?.takeIf { it.optBoolean("enabled") }?.optString("message")?.ifBlank { "BADSHAH AI is under maintenance." }
    }.getOrNull()
    suspend fun announcements(): List<Pair<String, String>> = runCatching {
