package dev.pages.badshah222ai.data.voice

import dev.pages.badshah222ai.data.ai.http
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONObject
import java.io.IOException

class ElevenException(val code: String, val userMessage: String) : Exception(userMessage)
data class ElevenVoice(val id: String, val name: String, val category: String)

/** OPTIONAL premium voices. Completely independent of Gemini/Groq. The user supplies their own key. */
class ElevenLabsClient {
    private val base = "https://api.elevenlabs.io/v1"

    suspend fun listVoices(key: String): List<ElevenVoice> = withContext(Dispatchers.IO) {
        try {
            http.newCall(Request.Builder().url("$base/voices").header("xi-api-key", key).build()).execute().use { r ->
                val body = r.body?.string().orEmpty()
                if (!r.isSuccessful) throw map(r.code)
                val a = JSONObject(body).optJSONArray("voices") ?: return@use emptyList<ElevenVoice>()
                (0 until a.length()).map { a.getJSONObject(it).let { o -> ElevenVoice(o.getString("voice_id"), o.optString("name", "Voice"), o.optString("category", "")) } }
            }
        } catch (e: IOException) { throw ElevenException("network", "No connection to ElevenLabs.") }
    }

    suspend fun synthesize(key: String, voiceId: String, text: String): ByteArray = withContext(Dispatchers.IO) {
        val payload = JSONObject().put("text", text).put("model_id", "eleven_multilingual_v2").toString()
        try {
            http.newCall(Request.Builder().url("$base/text-to-speech/$voiceId?output_format=mp3_44100_128")
                .header("xi-api-key", key).header("Accept", "audio/mpeg")
                .post(payload.toRequestBody("application/json".toMediaType())).build()).execute().use { r ->
                if (!r.isSuccessful) throw map(r.code)
                r.body?.bytes() ?: throw ElevenException("empty", "ElevenLabs returned no audio.")
            }
        } catch (e: IOException) { throw ElevenException("network", "No connection to ElevenLabs.") }
    }

    private fun map(code: Int) = when (code) {
        401 -> ElevenException("invalid_key", "ElevenLabs rejected the API key.")
        402, 429 -> ElevenException("quota", "ElevenLabs quota or rate limit reached.")
        404 -> ElevenException("voice_not_found", "That ElevenLabs voice is no longer available.")
        else -> ElevenException("http_$code", "ElevenLabs error (HTTP $code).")
    }
}

package dev.pages.badshah222ai.data.voice

import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.speech.RecognitionListener
import android.speech.RecognizerIntent
import android.speech.SpeechRecognizer
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow

/** Voice recognition via Android's SpeechRecognizer. Must be used from the main thread. */
class SpeechInput(private val context: Context) {
    private var rec: SpeechRecognizer? = null
    private val _listening = MutableStateFlow(false); val listening: StateFlow<Boolean> = _listening
    private val _level = MutableStateFlow(0f); val level: StateFlow<Float> = _level   // 0..1 microphone loudness

    fun isAvailable() = SpeechRecognizer.isRecognitionAvailable(context)

    fun start(languageTag: String, onPartial: (String) -> Unit, onResult: (String) -> Unit, onError: (String) -> Unit) {
        stop()
        if (!isAvailable()) { onError("This phone has no speech-recognition service. Install or enable Google (Speech Services) and try again."); return }
        val r = SpeechRecognizer.createSpeechRecognizer(context); rec = r
        r.setRecognitionListener(object : RecognitionListener {
            override fun onReadyForSpeech(p: Bundle?) { _listening.value = true }
            override fun onBeginningOfSpeech() {}
            override fun onRmsChanged(rms: Float) { _level.value = ((rms + 2f) / 12f).coerceIn(0f, 1f) }
            override fun onBufferReceived(b: ByteArray?) {}
            override fun onEndOfSpeech() { _listening.value = false; _level.value = 0f }
            override fun onError(error: Int) {
                _listening.value = false; _level.value = 0f
                onError(when (error) {
                    SpeechRecognizer.ERROR_NO_MATCH, SpeechRecognizer.ERROR_SPEECH_TIMEOUT -> "I did not hear anything. Tap the mic and try again."
                    SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS -> "Microphone permission is needed. Allow it in Permissions."
                    SpeechRecognizer.ERROR_NETWORK, SpeechRecognizer.ERROR_NETWORK_TIMEOUT -> "Speech recognition needs internet for this language."
                    SpeechRecognizer.ERROR_RECOGNIZER_BUSY -> "Speech recognition is busy. Try again in a moment."
                    else -> "Speech recognition failed (code $error)."
                })
            }
            override fun onResults(res: Bundle?) { _listening.value = false; _level.value = 0f
                val t = res?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)?.firstOrNull().orEmpty()
                if (t.isBlank()) onError("I did not catch that. Try again.") else onResult(t) }
            override fun onPartialResults(p: Bundle?) { p?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)?.firstOrNull()?.let(onPartial) }
            override fun onEvent(t: Int, p: Bundle?) {}
        })
        r.startListening(Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
            putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
            putExtra(RecognizerIntent.EXTRA_LANGUAGE, languageTag)
            putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS, true)
        })
    }

    fun stop() { rec?.runCatching { stopListening(); destroy() }; rec = null; _listening.value = false; _level.value = 0f }
}

package dev.pages.badshah222ai.data.voice

import android.content.Context
import android.media.MediaPlayer
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.speech.tts.UtteranceProgressListener
import dev.pages.badshah222ai.core.SecureStore
import dev.pages.badshah222ai.data.supabase.SupabaseApi
import dev.pages.badshah222ai.domain.VoiceInfo
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.withContext
import java.io.File
import java.util.Locale

/** Speaks replies using the REAL installed Android TTS voices, or (optionally, independently) ElevenLabs. */
class TtsManager(private val context: Context, private val store: SecureStore, private val cloud: SupabaseApi) {
    private var tts: TextToSpeech? = null
    private var player: MediaPlayer? = null
    private val eleven = ElevenLabsClient()
    private var onFinished: (() -> Unit)? = null

    private val _ready = MutableStateFlow(false); val ready: StateFlow<Boolean> = _ready
    private val _speaking = MutableStateFlow(false); val speaking: StateFlow<Boolean> = _speaking
    private val _voices = MutableStateFlow<List<VoiceInfo>>(emptyList()); val voices: StateFlow<List<VoiceInfo>> = _voices
    private val _engineName = MutableStateFlow(""); val engineName: StateFlow<String> = _engineName

    fun init() {
        if (tts != null) return
        tts = TextToSpeech(context) { status ->
            if (status == TextToSpeech.SUCCESS) {
                tts?.setOnUtteranceProgressListener(object : UtteranceProgressListener() {
                    override fun onStart(id: String?) { _speaking.value = true }
                    override fun onDone(id: String?) { if (id?.endsWith("_last") == true) finish() }
                    @Deprecated("Deprecated in Java") override fun onError(id: String?) { finish() }
                })
                refreshVoices(); _ready.value = true
            }
        }
    }

    fun refreshVoices() {
        val raw = runCatching { tts?.voices }.getOrNull().orEmpty()
        _voices.value = raw.map { VoiceInfo(it.name, it.locale.toLanguageTag(), it.isNetworkConnectionRequired, it.quality) }
        _engineName.value = runCatching { tts?.defaultEngine }.getOrNull().orEmpty()
    }

    fun isLanguageAvailable(tag: String): Boolean {
        val r = tts?.isLanguageAvailable(Locale.forLanguageTag(tag)) ?: return false
        return r >= TextToSpeech.LANG_AVAILABLE
    }

    private fun finish() { _speaking.value = false; val cb = onFinished; onFinished = null; cb?.invoke() }

    fun stop() { tts?.stop(); runCatching { player?.stop() }; player?.release(); player = null; _speaking.value = false; onFinished = null }

    /** Speaks with whichever engine the user chose. ElevenLabs falls back to Android TTS on failure. */
    suspend fun speak(text: String, onDone: (() -> Unit)? = null): String? {
        stop(); onFinished = onDone
        val key = store.elevenKey(); val vid = store.elevenVoiceId
        if (store.voiceEngine == "elevenlabs" && key != null && vid != null) {
            return try { speakEleven(key, vid, text); null }
            catch (e: ElevenException) { speakAndroid(text, store.ttsVoiceName, store.pitch, store.speed); "ElevenLabs: ${e.userMessage} Using the phone voice instead." }
        }
        speakAndroid(text, store.ttsVoiceName, store.pitch, store.speed); return null
    }

    fun speakAndroid(text: String, voiceName: String?, pitch: Float, speed: Float) {
        val engine = tts ?: run { finish(); return }
        engine.stopSilently()
        val v = voiceName?.let { n -> runCatching { engine.voices }.getOrNull()?.firstOrNull { it.name == n } }
        if (v != null) engine.setVoice(v) else engine.setLanguage(Locale.forLanguageTag(store.language))
        engine.setPitch(pitch.coerceIn(0.5f, 2f)); engine.setSpeechRate(speed.coerceIn(0.5f, 2f))
        val max = (TextToSpeech.getMaxSpeechInputLength() - 100).coerceAtLeast(500)
        val chunks = text.chunkedBySentence(max)
        chunks.forEachIndexed { i, c ->
            val id = "u$i" + if (i == chunks.lastIndex) "_last" else ""
            engine.speak(c, if (i == 0) TextToSpeech.QUEUE_FLUSH else TextToSpeech.QUEUE_ADD, Bundle(), id)
        }
    }
    private fun TextToSpeech.stopSilently() { runCatching { stop() } }

    private suspend fun speakEleven(key: String, voiceId: String, text: String) {
        val t0 = System.currentTimeMillis()
        val bytes = try { eleven.synthesize(key, voiceId, text.take(2500)) } catch (e: ElevenException) {
            cloud.recordUsage("elevenlabs", "eleven_multilingual_v2", "tts", false, 0, 0, null, e.code); throw e
        }
        cloud.recordUsage("elevenlabs", "eleven_multilingual_v2", "tts", true, text.length.toLong(), 0, (System.currentTimeMillis() - t0).toInt(), null)
        val f = withContext(Dispatchers.IO) { File(context.cacheDir, "eleven_tts.mp3").also { it.writeBytes(bytes) } }
        val mp = MediaPlayer()
        mp.setDataSource(f.absolutePath)
        mp.setOnCompletionListener { it.release(); if (player === it) player = null; finish() }
        mp.setOnErrorListener { m, _, _ -> m.release(); finish(); true }
        mp.prepare(); player = mp; _speaking.value = true; mp.start()
    }

    fun shutdown() { stop(); tts?.shutdown(); tts = null }
}

internal fun String.chunkedBySentence(max: Int): List<String> {
    if (length <= max) return listOf(this)
    val out = mutableListOf<String>(); val sb = StringBuilder()
    for (s in split(Regex("(?<=[.!?۔\\n])\\s+"))) {
        if (sb.length + s.length + 1 > max && sb.isNotEmpty()) { out += sb.toString(); sb.clear() }
        if (s.length > max) { s.chunked(max).forEach { out += it } } else { if (sb.isNotEmpty()) sb.append(' '); sb.append(s) }
    }
    if (sb.isNotEmpty()) out += sb.toString()
    return out
}

