/**
 * BADSHAH AI — Firebase Cloud Functions
 * =====================================
 * Project:        badshah-ai-badshah222  (REAL — created in the Firebase Console, 2026-11-15)
 * Android app:    dev.pages.badshah222ai
 * Supabase:       https://aghlacmqlagmigoznxlm.supabase.co (project ref aghlacmqlagmigoznxlm)
 *
 * What lives here (see docs/03-SUPABASE-JWT-INTEGRATION.md):
 *
 *  1. setSupabaseClaims  — HTTPS callable. Stamps the Firebase custom claims
 *                          { role: "authenticated", supabase_role: "authenticated" }
 *                          onto the signed-in caller so they appear in the
 *                          caller's Firebase ID token after a refresh.
 *
 *  2. beforeUserCreated  — v2 identity BLOCKING function. Adds the same
 *                          claims automatically at sign-up.
 *                          IMPORTANT: blocking functions only run if they are
 *                          enabled in the Firebase Console:
 *                          Authentication -> Settings -> Blocking functions.
 *                          If they are not enabled, this export is ignored
 *                          and the app must call setSupabaseClaims instead.
 *
 *  3. mintSupabaseToken  — OPTIONAL callable, Option B of Doc 03. Mints a
 *                          short-lived Supabase-compatible JWT for the
 *                          caller. Only needed if Supabase Third-Party Auth
 *                          (Option A, recommended) cannot be used.
 *                          It signs with the Supabase JWT secret, which is
 *                          read ONLY from process.env.SUPABASE_JWT_SECRET
 *                          (populated from Firebase Secret Manager via
 *                          `firebase functions:secrets:set SUPABASE_JWT_SECRET`).
 *                          THE SECRET VALUE MUST NEVER APPEAR IN THIS FILE,
 *                          IN THE REPO, OR IN ANY ZIP.
 *
 * Deployment requires the Blaze plan — see docs/05-TESTING-AND-DEPLOYMENT.md.
 */

"use strict";

const { onCall, HttpsError } = require("firebase-functions/v2/https");
const { beforeUserCreated } = require("firebase-functions/v2/identity");
const { logger } = require("firebase-functions");
const admin = require("firebase-admin");
const jwt = require("jsonwebtoken");

admin.initializeApp();

// Supabase project URL (public client configuration — not a secret).
const SUPABASE_URL = "https://aghlacmqlagmigoznxlm.supabase.co";
// Issuer Supabase expects on tokens it issued / accepts as its own (Option B).
const SUPABASE_ISSUER = `${SUPABASE_URL}/auth/v1`;

// The custom claims every BADSHAH AI user carries. `role: "authenticated"`
// is the claim shape the Supabase integration expects (Doc 03, section A.5);
// `supabase_role` is kept as an explicit, unambiguous copy.
const SUPABASE_CLAIMS = {
  role: "authenticated",
  supabase_role: "authenticated",
};

/**
 * 1) setSupabaseClaims — HTTPS callable (v2 onCall).
 *
 * Requires an authenticated caller (request.auth). Sets the Supabase claims
 * on the caller's Firebase user record via the Admin SDK. The claims appear
 * in the caller's ID token after the client forces a refresh
 * (getIdToken(true)).
 *
 * Client call (Android / Kotlin, conceptually):
 *   Firebase.functions.getHttpsCallable("setSupabaseClaims").call()
 */
exports.setSupabaseClaims = onCall(async (request) => {
  if (!request.auth) {
    throw new HttpsError(
      "unauthenticated",
      "You must be signed in to set Supabase claims."
    );
  }

  const uid = request.auth.uid;

  await admin.auth().setCustomUserClaims(uid, { ...SUPABASE_CLAIMS });

  logger.info("Supabase claims set", { uid });

  return {
    success: true,
    uid,
    claims: { ...SUPABASE_CLAIMS },
    // Tell the client exactly what to do next.
    next: "Call getIdToken(true) to refresh your ID token and pick up the new claims.",
  };
});

/**
 * 2) beforeUserCreated — v2 identity blocking function.
 *
 * Runs BEFORE a new user account is created (sign-up with any provider).
 * Returning customClaims here attaches them to the new user, so the very
 * first ID token already carries role: "authenticated".
 *
 * REMINDER: this only executes when blocking functions are enabled in the
 * Firebase Console (Authentication -> Settings -> Blocking functions) and
 * this function is deployed and selected there. Until then, rely on
 * setSupabaseClaims (above), which the app calls right after sign-in.
 */
exports.beforeUserCreated = beforeUserCreated((event) => {
  const user = event.data;
  logger.info("New user signing up — stamping Supabase claims", {
    uid: user ? user.uid : undefined,
  });

  return {
    customClaims: { ...SUPABASE_CLAIMS },
  };
});

/**
 * 3) mintSupabaseToken — OPTIONAL HTTPS callable (Doc 03, Option B ONLY).
 *
 * Signs a Supabase-compatible JWT for the authenticated caller:
 *   role = "authenticated"   (Postgres role PostgREST switches to)
 *   sub  = Firebase UID      (becomes auth.jwt() ->> 'sub' in RLS)
 *   aud  = "authenticated"
 *   iss  = <Supabase URL>/auth/v1
 *   exp  = at most 1 hour from issue
 *
 * The signing secret comes from Firebase Secret Manager, bound to this
 * function through the `secrets` option below and exposed at runtime as
 * process.env.SUPABASE_JWT_SECRET. If it is not set, this function throws
 * a clear error and mints NOTHING — it never falls back to an unsigned or
 * hard-coded token.
 *
 * Prefer Option A (Supabase Third-Party Auth) whenever it is available:
 * it needs no shared secret at all.
 */
exports.mintSupabaseToken = onCall(
  { secrets: ["SUPABASE_JWT_SECRET"] },
  async (request) => {
    if (!request.auth) {
      throw new HttpsError(
        "unauthenticated",
        "You must be signed in to mint a Supabase token."
      );
    }

    const secret = process.env.SUPABASE_JWT_SECRET;
    if (!secret) {
      throw new HttpsError(
        "failed-precondition",
        "SUPABASE_JWT_SECRET is not configured. Set it with " +
          "`firebase functions:secrets:set SUPABASE_JWT_SECRET` " +
          "(value from Supabase Dashboard -> Project Settings -> API -> " +
          "JWT Settings). See docs/03-SUPABASE-JWT-INTEGRATION.md, Option B."
      );
    }

    const uid = request.auth.uid;
    const email = (request.auth.token && request.auth.token.email) || null;

    const payload = {
      role: "authenticated",
      firebase_uid: uid,
    };
    if (email) {
      payload.email = email;
    }

    const token = jwt.sign(payload, secret, {
      algorithm: "HS256",
      subject: uid, // sub = Firebase UID
      audience: "authenticated", // aud
      issuer: SUPABASE_ISSUER, // iss = https://aghlacmqlagmigoznxlm.supabase.co/auth/v1
      expiresIn: "1h", // exp — never longer than 1 hour
    });

    logger.info("Supabase token minted (Option B)", { uid });

    return {
      success: true,
      token,
      tokenType: "Bearer",
      expiresInSeconds: 3600,
      // Client usage: send the token as `Authorization: Bearer <token>`
      // to Supabase REST/Storage together with the anon key as `apikey`.
    };
  }
);

// Small WebCrypto helpers (work in Deno and Node 20+).
const enc = new TextEncoder();

export async function sha256Hex(input: string): Promise<string> {
  const buf = await crypto.subtle.digest("SHA-256", enc.encode(input));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export function randomToken(bytes = 32): string {
  const a = crypto.getRandomValues(new Uint8Array(bytes));
  return btoa(String.fromCharCode(...a)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

/** Constant-time string comparison (length is not secret here). */
export function timingSafeEqual(a: string, b: string): boolean {
  const x = enc.encode(a), y = enc.encode(b);
  if (x.length !== y.length) return false;
  let r = 0;
  for (let i = 0; i < x.length; i++) r |= x[i] ^ y[i];
  return r === 0;
}

// Configurable server-side email. Provider: Resend (https://resend.com).
// Configure with Edge Function secrets: RESEND_API_KEY, EMAIL_FROM.
// If either is missing nothing is sent and the outbox row is marked 'skipped'.
export interface EmailResult { status: "sent" | "failed" | "skipped"; error?: string }

export async function sendEmail(
  env: { get(k: string): string | undefined },
  to: string, subject: string, text: string,
  fetchFn: typeof fetch = fetch,
): Promise<EmailResult> {
  const key = env.get("RESEND_API_KEY"), from = env.get("EMAIL_FROM");
  if (!key || !from) return { status: "skipped", error: "email provider not configured (RESEND_API_KEY / EMAIL_FROM)" };
  try {
    const r = await fetchFn("https://api.resend.com/emails", {
      method: "POST",
      headers: { "Authorization": `Bearer ${key}`, "Content-Type": "application/json" },
      body: JSON.stringify({ from, to: [to], subject, text }),
    });
    if (!r.ok) return { status: "failed", error: `provider HTTP ${r.status}` };
    return { status: "sent" };
  } catch (e) {
    return { status: "failed", error: String(e).slice(0, 200) };
  }
}

// BADSHAH AI admin API. Never called by browsers directly: the Cloudflare
// Worker adds x-gateway-secret, x-client-ip and x-admin-token (from an
// HttpOnly cookie). Everything here runs with the service role.
import { randomToken, sha256Hex, timingSafeEqual } from "../_shared/crypto.ts";
import { sendEmail } from "../_shared/email.ts";

// deno-lint-ignore no-explicit-any
type Sb = any;
export interface Env { get(k: string): string | undefined }
export interface Deps { sb: Sb; env: Env; fetchFn?: typeof fetch; sleep?: (ms: number) => Promise<void> }

const json = (status: number, body: unknown) =>
  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store" } });
const bad = (msg: string, status = 400) => json(status, { error: msg });

const TICKET_STATUS = ["open", "in_progress", "resolved", "closed"];
const SECRETISH = /(secret|api[_-]?key|token|password|passwd|private)/i;
const str = (v: unknown, max: number) => (typeof v === "string" ? v.trim().slice(0, max) : "");
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function hasSecretKey(v: unknown): boolean {
  if (Array.isArray(v)) return v.some(hasSecretKey);
  if (v && typeof v === "object") return Object.entries(v).some(([k, x]) => SECRETISH.test(k) || hasSecretKey(x));
  return false;
}

export function createHandler(deps: Deps) {
  const { sb, env } = deps;
  const sleep = deps.sleep ?? ((ms: number) => new Promise((r) => setTimeout(r, ms)));
  const rpc = async (fn: string, args: Record<string, unknown> = {}) => {
    const { data, error } = await sb.rpc(fn, args);
    if (error) throw new Error(`${fn}: ${error.message}`);
    return data;
  };
  const audit = (action: string, target: string | null, details: Record<string, unknown> = {}) =>
    rpc("admin_write_audit", { p_action: action, p_target_user_id: target, p_details: details }).catch(() => {});

  return async function handle(req: Request): Promise<Response> {
    if (req.method !== "POST") return bad("method not allowed", 405);
    const gw = env.get("GATEWAY_SECRET") ?? "";
    if (gw.length < 24 || !timingSafeEqual(req.headers.get("x-gateway-secret") ?? "", gw)) {
      return bad("forbidden", 403); // direct calls (not via the Worker) are rejected
    }
    let body: Record<string, unknown>;
    try { body = await req.json(); } catch { return bad("invalid JSON"); }
    const action = str(body.action, 60);
    const ip = str(req.headers.get("x-client-ip"), 80) || "unknown";
    const ipHash = await sha256Hex(`${ip}|${env.get("IP_HASH_PEPPER") ?? "pepper"}`);

    try {
      // ---------------- LOGIN (password only) ----------------
      if (action === "login") {
        const pw = typeof body.password === "string" ? body.password : "";
        if (!pw || pw.length > 256) return bad("invalid credentials", 401);
        if (!(await rpc("admin_rate_limit_ok", { p_ip_hash: ipHash }))) {
          return json(429, { error: "Too many failed attempts. Try again in 15 minutes." });
        }
        const ok = await rpc("verify_admin_password", { p_password: pw });
        await rpc("admin_record_attempt", { p_ip_hash: ipHash, p_success: ok === true });
        if (ok !== true) { await sleep(400); await audit("admin_login_failed", null, {}); return bad("invalid credentials", 401); }
        const token = randomToken(32);
        const ttl = Math.min(Math.max(parseInt(env.get("ADMIN_SESSION_MINUTES") ?? "120"), 5), 720);
        const expires_at = await rpc("admin_create_session", { p_token_hash: await sha256Hex(token), p_ttl_minutes: ttl });
        await audit("admin_login", null, {});
        return json(200, { token, expires_at });
      }

      // ---------------- everything else needs a session ----------------
      const token = str(req.headers.get("x-admin-token"), 200);
      if (!token) return bad("unauthorized", 401);
      const tokenHash = await sha256Hex(token);
      const idle = Math.min(Math.max(parseInt(env.get("ADMIN_IDLE_MINUTES") ?? "30"), 5), 240);
      const sid = await rpc("admin_validate_session", { p_token_hash: tokenHash, p_idle_minutes: idle });
      if (!sid) return bad("session expired", 401);

      switch (action) {
        case "session": return json(200, { ok: true, session_id: sid });
        case "logout":
          await rpc("admin_revoke_session", { p_token_hash: tokenHash });
          await audit("admin_logout", null, {});
          return json(200, { ok: true });

        // ---------- analytics ----------
        case "overview": return json(200, await rpc("admin_overview"));
        case "analytics.login": return json(200, await rpc("admin_login_analytics", { p_days: Number(body.days) || 30 }));
        case "analytics.api": return json(200, await rpc("admin_api_analytics", { p_days: Number(body.days) || 30 }));

        // ---------- users ----------
        case "users.list": {
          const st = ["all", "active", "blocked"].includes(String(body.status)) ? String(body.status) : "all";
          return json(200, await rpc("admin_list_users", {
            p_search: str(body.search, 100) || null, p_status: st,
            p_limit: Math.min(Number(body.limit) || 25, 100), p_offset: Math.max(Number(body.offset) || 0, 0),
          }));
        }
        case "users.detail": {
          const id = str(body.user_id, 200); if (!id) return bad("user_id required");
          return json(200, await rpc("admin_user_detail", { p_user_id: id }));
        }
        case "users.block":
        case "users.unblock": {
          const id = str(body.user_id, 200); if (!id) return bad("user_id required");
          const blocked = action === "users.block";
          const { data, error } = await sb.from("profiles").update({ is_blocked: blocked, updated_at: new Date().toISOString() }).eq("id", id).select("id");
          if (error) throw new Error(error.message);
          if (!data?.length) return bad("user not found", 404);
          await audit(blocked ? "user_blocked" : "user_unblocked", id, {});
          return json(200, { ok: true, is_blocked: blocked });
        }
        case "users.update": {
          const id = str(body.user_id, 200); if (!id) return bad("user_id required");
          const patch: Record<string, unknown> = { updated_at: new Date().toISOString() };
          if (typeof body.display_name === "string") patch.display_name = str(body.display_name, 120);
          if (Object.keys(patch).length < 2) return bad("nothing to update");
          const { data, error } = await sb.from("profiles").update(patch).eq("id", id).select("id");
          if (error) throw new Error(error.message);
          if (!data?.length) return bad("user not found", 404);
          await audit("user_updated", id, { fields: Object.keys(patch).filter((k) => k !== "updated_at") });
          return json(200, { ok: true });
        }
        case "users.delete": {
          const id = str(body.user_id, 200); if (!id) return bad("user_id required");
          if (body.confirm !== id) return bad("confirmation must equal the user id");
          const { data, error } = await sb.from("profiles").delete().eq("id", id).select("id");
          if (error) throw new Error(error.message);
          if (!data?.length) return bad("user not found", 404);
          await audit("user_deleted", id, {});
          return json(200, {
            ok: true,
            note: "Database records deleted. The Firebase Auth account still exists; if the person signs in again an empty profile is recreated. Prefer Block, or also delete the account in Firebase Console > Authentication.",
          });
        }

        // ---------- support ----------
        case "tickets.list": {
          let q = sb.from("support_tickets").select("id,user_id,subject,category,status,priority,created_at,updated_at").order("updated_at", { ascending: false }).limit(200);
          const st = str(body.status, 20);
          if (st) { if (!TICKET_STATUS.includes(st)) return bad("bad status"); q = q.eq("status", st); }
          const { data, error } = await q; if (error) throw new Error(error.message);
          const ids = [...new Set((data ?? []).map((t: { user_id: string }) => t.user_id))];
          const { data: ps } = ids.length ? await sb.from("profiles").select("id,email,display_name").in("id", ids) : { data: [] };
          const byId = new Map((ps ?? []).map((p: { id: string }) => [p.id, p]));
          return json(200, { tickets: (data ?? []).map((t: { user_id: string }) => ({ ...t, user: byId.get(t.user_id) ?? null })) });
        }
        case "tickets.get": {
          const id = str(body.ticket_id, 40); if (!uuidRe.test(id)) return bad("bad ticket_id");
          const { data: t } = await sb.from("support_tickets").select("*").eq("id", id).maybeSingle();
          if (!t) return bad("ticket not found", 404);
          const { data: msgs } = await sb.from("support_messages").select("id,sender_type,message,created_at").eq("ticket_id", id).order("created_at", { ascending: true });
          const { data: p } = await sb.from("profiles").select("id,email,display_name").eq("id", t.user_id).maybeSingle();
          return json(200, { ticket: t, messages: msgs ?? [], user: p ?? null });
        }
        case "tickets.reply": {
          const id = str(body.ticket_id, 40); if (!uuidRe.test(id)) return bad("bad ticket_id");
          const text = str(body.message, 5000); if (!text) return bad("message required");
          const status = body.status ? str(body.status, 20) : "in_progress";
          if (!TICKET_STATUS.includes(status)) return bad("bad status");
          const { data: t } = await sb.from("support_tickets").select("id,user_id,subject").eq("id", id).maybeSingle();
          if (!t) return bad("ticket not found", 404);
          const ins = await sb.from("support_messages").insert({ ticket_id: id, sender_type: "admin", message: text });
          if (ins.error) throw new Error(ins.error.message);
          await sb.from("support_tickets").update({ admin_reply: text, status }).eq("id", id);
          const { data: p } = await sb.from("profiles").select("email,display_name").eq("id", t.user_id).maybeSingle();
          let email: { status: string; error?: string } = { status: "skipped", error: "user has no email on file" };
          if (p?.email) {
            const subject = `Re: ${t.subject} - BADSHAH AI Support`;
            const mail = `Hello ${p.display_name ?? ""},\n\n${text}\n\nYou can also read this reply in the BADSHAH AI app under Help Center.\n\n- BADSHAH AI Support`;
            email = await sendEmail(env, p.email, subject, mail, deps.fetchFn);
            await sb.from("email_outbox").insert({ ticket_id: id, to_email: p.email, subject, body: mail, status: email.status, error: email.error ?? null, sent_at: email.status === "sent" ? new Date().toISOString() : null });
          }
          await audit("ticket_reply", t.user_id, { ticket_id: id, status, email: email.status });
          return json(200, { ok: true, status, email });
        }
        case "tickets.status": {
          const id = str(body.ticket_id, 40); if (!uuidRe.test(id)) return bad("bad ticket_id");
          const status = str(body.status, 20); if (!TICKET_STATUS.includes(status)) return bad("bad status");
          const { data, error } = await sb.from("support_tickets").update({ status }).eq("id", id).select("id,user_id");
          if (error) throw new Error(error.message);
          if (!data?.length) return bad("ticket not found", 404);
          await audit("ticket_status", data[0].user_id, { ticket_id: id, status });
          return json(200, { ok: true });
        }

        // ---------- app management ----------
        case "announcements.list": {
          const { data } = await sb.from("announcements").select("*").order("created_at", { ascending: false }).limit(100);
          return json(200, { announcements: data ?? [] });
        }
        case "announcements.save": {
          const title = str(body.title, 200), content = str(body.content, 5000);
          if (!title || !content) return bad("title and content required");
          const row = { title, content, is_published: body.is_published === true, updated_at: new Date().toISOString() };
          const id = str(body.id, 40);
          const r = id ? (uuidRe.test(id) ? await sb.from("announcements").update(row).eq("id", id).select("id") : null)
                       : await sb.from("announcements").insert(row).select("id");
          if (!r) return bad("bad id"); if (r.error) throw new Error(r.error.message);
          await audit("announcement_saved", null, { id: r.data?.[0]?.id, published: row.is_published });
          return json(200, { ok: true, id: r.data?.[0]?.id });
        }
        case "announcements.delete": {
          const id = str(body.id, 40); if (!uuidRe.test(id)) return bad("bad id");
          await sb.from("announcements").delete().eq("id", id);
          await audit("announcement_deleted", null, { id });
          return json(200, { ok: true });
        }
        case "config.list": {
          const { data } = await sb.from("app_config").select("*").order("config_key");
          return json(200, { config: data ?? [] });
        }
        case "config.set": {
          const key = str(body.key, 60);
          if (!/^[a-z0-9_.-]{1,60}$/.test(key)) return bad("invalid key");
          if (SECRETISH.test(key)) return bad("secrets must never be stored in app_config");
          const raw = JSON.stringify(body.value ?? null);
          if (raw.length > 10000) return bad("value too large");
          if (hasSecretKey(body.value)) return bad("secrets must never be stored in app_config");
          const { error } = await sb.from("app_config").upsert({ config_key: key, config_value: body.value ?? {}, updated_at: new Date().toISOString() });
          if (error) throw new Error(error.message);
          await audit("config_set", null, { key });
          return json(200, { ok: true });
        }
        case "voices.list": {
          const { data } = await sb.from("voice_profiles").select("*").order("sort_order").limit(200);
          return json(200, { voices: data ?? [] });
        }
        case "voices.save": {
          const id = str(body.id, 60);
          if (!/^[a-z0-9_-]{2,60}$/.test(id)) return bad("id must be lowercase letters, digits, - or _");
          const row = {
            id, label: str(body.label, 80), category: str(body.category, 30) || "natural", language: str(body.language, 20) || "en",
            engine: ["android_tts", "elevenlabs"].includes(String(body.engine)) ? String(body.engine) : "android_tts",
            pitch: Math.min(Math.max(Number(body.pitch) || 1, 0.5), 2), speed: Math.min(Math.max(Number(body.speed) || 1, 0.5), 2),
            is_enabled: body.is_enabled !== false, sort_order: Math.trunc(Number(body.sort_order) || 100),
            notes: str(body.notes, 300) || null, updated_at: new Date().toISOString(),
          };
          if (!row.label) return bad("label required");
          const { error } = await sb.from("voice_profiles").upsert(row);
          if (error) throw new Error(error.message);
          await audit("voice_saved", null, { id });
          return json(200, { ok: true });
        }
        case "voices.delete": {
          const id = str(body.id, 60); if (!id) return bad("id required");
          await sb.from("voice_profiles").delete().eq("id", id);
          await audit("voice_deleted", null, { id });
          return json(200, { ok: true });
        }

        // ---------- security ----------
        case "security.overview":
          return json(200, {
            attempts: await rpc("admin_list_attempts", { p_limit: 100 }),
            audit: await rpc("admin_list_audit", { p_limit: 100 }),
            sessions: await rpc("admin_list_sessions", { p_limit: 50 }),
            current_session_id: sid,
          });
        case "security.revoke_session": {
          const target = str(body.session_id, 40); if (!uuidRe.test(target)) return bad("bad session_id");
          const n = await rpc("admin_revoke_session", { p_session_id: target });
          await audit("session_revoked", null, { session_id: target });
          return json(200, { ok: true, revoked: n });
        }
        case "security.revoke_others": {
          const n = await rpc("admin_revoke_all_sessions", { p_except_token_hash: tokenHash });
          await audit("sessions_revoked_others", null, { count: n });
          return json(200, { ok: true, revoked: n });
        }
        case "security.change_password": {
          const cur = typeof body.current_password === "string" ? body.current_password : "";
          const next = typeof body.new_password === "string" ? body.new_password : "";
          if (next.length < 12) return bad("new password must be at least 12 characters");
          if (!(await rpc("admin_rate_limit_ok", { p_ip_hash: ipHash }))) return json(429, { error: "Too many failed attempts." });
          const ok = await rpc("verify_admin_password", { p_password: cur });
          await rpc("admin_record_attempt", { p_ip_hash: ipHash, p_success: ok === true });
          if (ok !== true) return bad("current password is wrong", 401);
          if (!(await rpc("change_admin_password", { p_new_password: next }))) return bad("password rejected");
          await rpc("admin_revoke_all_sessions", { p_except_token_hash: tokenHash });
          await audit("admin_password_changed", null, {});
          return json(200, { ok: true, note: "All other admin sessions were signed out." });
        }
        default: return bad("unknown action", 404);
      }
    } catch (e) {
      console.error("admin-api error", action, String(e));
      return json(500, { error: "internal error" }); // never leak DB details
    }
  };
}

import { createClient } from "npm:@supabase/supabase-js@2";
import { createHandler } from "./handler.ts";

// SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are injected by Supabase automatically.
const sb = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!, {
  auth: { persistSession: false, autoRefreshToken: false },
});
Deno.serve(createHandler({ sb, env: Deno.env }));

-- =====================================================
-- BADSHAH AI - MIGRATION 002
-- Extends 20261115000001_core_schema.sql (does not repeat it).
--
-- Why this exists:
--  * Supabase's REST API does not expose the `private` schema, so
--    Edge Functions cannot touch admin_sessions / attempts / audit
--    directly. Service-role-only wrapper functions fix that.
--  * Admin analytics are computed in SQL (no private chat content).
--  * The Android app needs safe, validated ways to record logins and
--    AI usage (table grants only allow SELECT on those tables).
--  * Blocked users must actually be blocked by the database.
--  * Missing tables: voice_profiles, email_outbox.
-- Idempotent: safe to run more than once.
-- =====================================================

-- ---------- helpers ----------
create or replace function public.touch_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin new.updated_at = now(); return new; end; $$;

-- ---------- NEW TABLES ----------
create table if not exists public.voice_profiles (
    id text primary key,
    label text not null,
    category text not null default 'natural',
    language text not null default 'en',
    engine text not null default 'android_tts',
    pitch numeric not null default 1.0 check (pitch between 0.5 and 2.0),
    speed numeric not null default 1.0 check (speed between 0.5 and 2.0),
    is_enabled boolean not null default true,
    sort_order integer not null default 100,
    notes text,
    updated_at timestamptz not null default now()
);

create table if not exists public.email_outbox (
    id uuid primary key default gen_random_uuid(),
    ticket_id uuid references public.support_tickets(id) on delete set null,
    to_email text not null,
    subject text not null,
    body text not null,
    status text not null default 'pending' check (status in ('pending','sent','failed','skipped')),
    error text,
    created_at timestamptz not null default now(),
    sent_at timestamptz
);

alter table public.voice_profiles enable row level security;
alter table public.email_outbox  enable row level security;

drop policy if exists "voice_profiles_read_enabled" on public.voice_profiles;
create policy "voice_profiles_read_enabled" on public.voice_profiles
    for select to authenticated using (is_enabled = true);
-- email_outbox: RLS on, NO policies => unreachable except service_role.

revoke all on public.voice_profiles, public.email_outbox from anon, authenticated;
grant select on public.voice_profiles to authenticated;
grant all on public.voice_profiles, public.email_outbox to service_role;

create index if not exists idx_login_created   on public.login_events(created_at desc);
create index if not exists idx_usage_created   on public.ai_usage_events(created_at desc);
create index if not exists idx_tickets_status  on public.support_tickets(status, updated_at desc);
create index if not exists idx_support_msgs    on public.support_messages(ticket_id, created_at);
create index if not exists idx_outbox_status   on public.email_outbox(status, created_at);

drop trigger if exists trg_tickets_touch on public.support_tickets;
create trigger trg_tickets_touch before update on public.support_tickets
    for each row execute function public.touch_updated_at();

-- A new support message (user or admin) bumps the ticket.
create or replace function public.bump_ticket_on_message()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
    update public.support_tickets set updated_at = now() where id = new.ticket_id;
    return new;
end; $$;
drop trigger if exists trg_support_msg_bump on public.support_messages;
create trigger trg_support_msg_bump after insert on public.support_messages
    for each row execute function public.bump_ticket_on_message();

-- ---------- SEED NON-SECRET CONFIG ----------
insert into public.app_config (config_key, config_value) values
  ('maintenance', '{"enabled": false, "message": ""}'),
  ('min_app_version', '{"android": 1}'),
  ('social_links', '{}')
on conflict (config_key) do nothing;

-- =====================================================
-- BLOCKED USERS: enforced by the database, not only the UI
-- =====================================================
create or replace function public.is_blocked_user()
returns boolean language sql stable security definer set search_path = '' as $$
    select coalesce(
        (select p.is_blocked from public.profiles p
         where p.id = (select auth.jwt()->>'sub')), false);
$$;
revoke all on function public.is_blocked_user() from public, anon;
grant execute on function public.is_blocked_user() to authenticated, service_role;

do $$
declare t text; c text;
begin
  foreach t in array array['conversations','messages','support_tickets','support_messages',
                           'user_preferences','user_provider_settings','app_events'] loop
    foreach c in array array['insert','update'] loop
      if c = 'update' and t in ('messages','support_tickets','support_messages','app_events') then
        continue; -- those tables have no UPDATE grant for clients
      end if;
      execute format('drop policy if exists %I on public.%I', 'blocked_users_no_'||c, t);
      if c = 'insert' then
        execute format('create policy %I on public.%I as restrictive for insert to authenticated with check (not public.is_blocked_user())', 'blocked_users_no_'||c, t);
      else
        execute format('create policy %I on public.%I as restrictive for update to authenticated using (not public.is_blocked_user())', 'blocked_users_no_'||c, t);
      end if;
    end loop;
  end loop;
end $$;

-- The app talks to Gemini/Groq directly with the user's own key, so the
-- client itself must be able to save assistant replies to its own chat.
drop policy if exists "messages_insert_own_chat" on public.messages;
create policy "messages_insert_own_chat" on public.messages
    for insert to authenticated
    with check (
        user_id = (select auth.jwt()->>'sub')
        and role in ('user','assistant')
        and exists (select 1 from public.conversations c
                    where c.id = conversation_id
                      and c.user_id = (select auth.jwt()->>'sub'))
    );

-- =====================================================
-- APP-FACING RPCs (authenticated users, own data only)
-- =====================================================
create or replace function public.app_touch_profile(
    p_email text, p_display_name text, p_avatar_url text)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare uid text := (select auth.jwt()->>'sub'); blocked boolean;
begin
    if uid is null then raise exception 'not authenticated' using errcode = '28000'; end if;
    insert into public.profiles (id, email, display_name, avatar_url, last_seen_at)
    values (uid, left(p_email,320), left(p_display_name,120), left(p_avatar_url,1000), now())
    on conflict (id) do update set
        email = coalesce(excluded.email, public.profiles.email),
        display_name = coalesce(public.profiles.display_name, excluded.display_name),
        avatar_url = coalesce(public.profiles.avatar_url, excluded.avatar_url),
        last_seen_at = now(), updated_at = now();
    select is_blocked into blocked from public.profiles where id = uid;
    return jsonb_build_object('user_id', uid, 'is_blocked', blocked);
end; $$;

create or replace function public.app_record_login(
    p_provider text, p_event_type text default 'login', p_device text default 'android')
returns void language plpgsql security definer set search_path = '' as $$
declare uid text := (select auth.jwt()->>'sub');
begin
    if uid is null then raise exception 'not authenticated' using errcode = '28000'; end if;
    if p_event_type not in ('login','register','logout') then
        raise exception 'bad event_type'; end if;
    if not exists (select 1 from public.profiles where id = uid) then
        raise exception 'profile missing; call app_touch_profile first'; end if;
    insert into public.login_events (user_id, provider, event_type, success, device_type)
    values (uid, left(p_provider,40), p_event_type, true, left(p_device,40));
end; $$;

create or replace function public.app_record_usage(
    p_provider text, p_model text, p_event_type text, p_success boolean,
    p_input_tokens bigint default 0, p_output_tokens bigint default 0,
    p_latency_ms integer default null, p_error_code text default null)
returns void language plpgsql security definer set search_path = '' as $$
declare uid text := (select auth.jwt()->>'sub');
begin
    if uid is null then raise exception 'not authenticated' using errcode = '28000'; end if;
    if p_provider not in ('gemini','groq','elevenlabs','android_tts') then
        raise exception 'unknown provider'; end if;
    if public.is_blocked_user() then raise exception 'account blocked'; end if;
    insert into public.ai_usage_events
      (user_id, provider, model_name, event_type, success, input_tokens, output_tokens, latency_ms, error_code)
    values (uid, p_provider, left(p_model,120), left(coalesce(p_event_type,'chat'),40), coalesce(p_success,false),
            greatest(coalesce(p_input_tokens,0),0), greatest(coalesce(p_output_tokens,0),0),
            p_latency_ms, left(p_error_code,80));
end; $$;

revoke all on function public.app_touch_profile(text,text,text),
                       public.app_record_login(text,text,text),
                       public.app_record_usage(text,text,text,boolean,bigint,bigint,integer,text)
    from public, anon;
grant execute on function public.app_touch_profile(text,text,text),
                          public.app_record_login(text,text,text),
                          public.app_record_usage(text,text,text,boolean,bigint,bigint,integer,text)
    to authenticated;

