// Shared test harness: migrated PGlite DB + PostgREST-like supabase-js shim.
import { PGlite } from '@electric-sql/pglite';
import { pgcrypto } from '@electric-sql/pglite/contrib/pgcrypto';
import fs from 'node:fs'; import path from 'node:path'; import { fileURLToPath } from 'node:url';

const dir = path.dirname(fileURLToPath(import.meta.url));
const mig = (f) => fs.readFileSync(path.join(dir, '../migrations', f), 'utf8');
export const TEST_PW = 'test-only-password-123';
export const db = new PGlite({ extensions: { pgcrypto } });
await db.exec(`create schema extensions; create schema auth;
 create role anon nologin; create role authenticated nologin; create role service_role nologin bypassrls;
 create function auth.jwt() returns jsonb language sql stable as $$ select '{}'::jsonb $$;
 grant usage on schema auth, extensions to anon, authenticated, service_role;`);
await db.exec(mig('20261115000001_core_schema.sql').replace('__INITIAL_ADMIN_PASSWORD__', TEST_PW));
await db.exec(mig('20261115000002_admin_and_app_extensions.sql'));
// ---- minimal supabase-js shim (service role) ----
const id = (s) => { if (!/^[a-z_]+$/.test(s)) throw new Error('bad ident'); return s; };
class Q {
  constructor(t) { this.t = id(t); this.op = 'select'; this.w = []; this.vals = []; this.ord = ''; this.lim = ''; this.cols = '*'; this.ret = false; this.one = false; }
  _p(v) { this.vals.push(v); return `$${this.vals.length}`; }
  select(c = '*') { if (this.op === 'select') this.cols = c.split(',').map((x) => x.trim() === '*' ? '*' : id(x.trim())).join(','); else { this.ret = true; } return this; }
  insert(r) { this.op = 'insert'; this.row = r; return this; }
  upsert(r) { this.op = 'upsert'; this.row = r; return this; }
  update(r) { this.op = 'update'; this.row = r; return this; }
  delete() { this.op = 'delete'; return this; }
  eq(c, v) { this.w.push(`${id(c)} = ${this._p(v)}`); return this; }
  in(c, a) { this.w.push(`${id(c)} = any(${this._p(a)})`); return this; }
  order(c, o = {}) { this.ord = ` order by ${id(c)} ${o.ascending === false ? 'desc' : 'asc'}`; return this; }
  limit(n) { this.lim = ` limit ${Number(n)}`; return this; }
  maybeSingle() { this.one = true; return this; }
  async then(res, rej) { try { res(await this.run()); } catch (e) { res({ data: null, error: { message: e.message } }); } }
  async run() {
    const where = this.w.length ? ` where ${this.w.join(' and ')}` : '';
    let sql;
    if (this.op === 'select') sql = `select ${this.cols} from public.${this.t}${where}${this.ord}${this.lim}`;
    else if (this.op === 'delete') sql = `delete from public.${this.t}${where}${this.ret ? ' returning *' : ''}`;
    else if (this.op === 'update') { const ks = Object.keys(this.row).map(id); const sets = ks.map((k) => `${k} = ${this._p(this.row[k])}`); sql = `update public.${this.t} set ${sets.join(',')}${where}${this.ret ? ' returning *' : ''}`; }
    else { const ks = Object.keys(this.row).map(id); const ph = ks.map((k) => this._p(typeof this.row[k] === 'object' && this.row[k] !== null && !(this.row[k] instanceof Date) ? JSON.stringify(this.row[k]) : this.row[k]));
      const pk = { app_config: 'config_key', voice_profiles: 'id' }[this.t];
      sql = `insert into public.${this.t} (${ks.join(',')}) values (${ph.join(',')})` + (this.op === 'upsert' ? ` on conflict (${pk}) do update set ${ks.map((k) => `${k}=excluded.${k}`).join(',')}` : '') + (this.ret ? ' returning *' : ''); }
    await db.exec('set role service_role');
    try { const r = await db.query(sql, this.vals); return { data: this.one ? (r.rows[0] ?? null) : r.rows, error: null }; }
    catch (e) { return { data: null, error: { message: e.message } }; } finally { await db.exec('reset role'); }
  }
}
export const sb = {
  from: (t) => new Q(t),
  async rpc(fn, args = {}) {
    const ks = Object.keys(args), names = ks.map((k, i) => `${k} => $${i + 1}`).join(',');
    await db.exec('set role service_role');
    try { const r = await db.query(`select public.${id(fn)}(${names}) as r`, ks.map((k) => args[k])); return { data: r.rows[0].r, error: null }; }
    catch (e) { return { data: null, error: { message: e.message } }; } finally { await db.exec('reset role'); }
  },
};

