const env = (calls, edge) => ({
  GATEWAY_SECRET: 'gw-secret-for-tests', SUPABASE_URL: 'https://x.supabase.co',
  ASSETS: { fetch: async (r) => new Response('ASSET:' + new URL(r.url).pathname, { headers: { 'content-type': 'text/html' } }) },
});
let edgeImpl;
globalThis.fetch = async (url, init) => edgeImpl(url, init);
const api = (body, { cookie, origin = 'https://site.test', xrw = 'badshah-admin' } = {}) =>
  new Request('https://site.test/admin/api', { method: 'POST', headers: { Origin: origin, 'x-requested-with': xrw, 'CF-Connecting-IP': '7.7.7.7', ...(cookie ? { Cookie: cookie } : {}) }, body: JSON.stringify(body) });
const edgeJson = (status, obj) => new Response(JSON.stringify(obj), { status });

test('login: token moves into HttpOnly cookie and is NOT in the response body', async () => {
  let seen; edgeImpl = async (u, i) => { seen = { u, i }; return edgeJson(200, { token: 'TOK123', expires_at: new Date(Date.now() + 3600e3).toISOString() }); };
  const res = await worker.fetch(api({ action: 'login', password: 'pw' }), env());
  const body = await res.json();
  assert.equal(res.status, 200); assert.equal(body.token, undefined);
  const sc = res.headers.get('Set-Cookie');
  assert.match(sc, /^__Host-badshah_admin=TOK123;/); for (const f of ['HttpOnly', 'Secure', 'SameSite=Strict', 'Path=/']) assert.ok(sc.includes(f), f);
  assert.equal(seen.u, 'https://x.supabase.co/functions/v1/admin-api');
  assert.equal(seen.i.headers['x-gateway-secret'], 'gw-secret-for-tests');
  assert.equal(seen.i.headers['x-client-ip'], '7.7.7.7');
  assert.equal(res.headers.get('X-Frame-Options'), 'DENY');
});
test('cookie is forwarded as x-admin-token on later calls', async () => {
  let seen; edgeImpl = async (u, i) => { seen = i; return edgeJson(200, { ok: true }); };
  await worker.fetch(api({ action: 'overview' }, { cookie: '__Host-badshah_admin=TOK123' }), env());
  assert.equal(seen.headers['x-admin-token'], 'TOK123');
});
test('CSRF: wrong Origin, missing Origin and missing custom header are rejected before reaching the backend', async () => {
  let hit = 0; edgeImpl = async () => { hit++; return edgeJson(200, {}); };
  assert.equal((await worker.fetch(api({ action: 'x' }, { origin: 'https://evil.test' }), env())).status, 403);
  assert.equal((await worker.fetch(api({ action: 'x' }, { xrw: 'nope' }), env())).status, 403);
  const noOrigin = new Request('https://site.test/admin/api', { method: 'POST', headers: { 'x-requested-with': 'badshah-admin' }, body: '{}' });
  assert.equal((await worker.fetch(noOrigin, env())).status, 403);
  assert.equal(hit, 0);
});
test('GET /admin/api is refused', async () => {
  assert.equal((await worker.fetch(new Request('https://site.test/admin/api'), env())).status, 405);
});
test('401 from backend clears the cookie', async () => {
  edgeImpl = async () => edgeJson(401, { error: 'session expired' });
  const res = await worker.fetch(api({ action: 'overview' }, { cookie: '__Host-badshah_admin=OLD' }), env());
  assert.equal(res.status, 401); assert.match(res.headers.get('Set-Cookie'), /Max-Age=0/);
});
test('logout clears cookie', async () => {
  edgeImpl = async () => edgeJson(200, { ok: true });
  const res = await worker.fetch(api({ action: 'logout' }, { cookie: '__Host-badshah_admin=T' }), env());
  assert.match(res.headers.get('Set-Cookie'), /^__Host-badshah_admin=; .*Max-Age=0/);
});
test('rate-limit 429 passes through to the browser', async () => {
  edgeImpl = async () => edgeJson(429, { error: 'Too many failed attempts.' });
  assert.equal((await worker.fetch(api({ action: 'login', password: 'x' }), env())).status, 429);
});
test('dashboard pages: no cookie -> redirect to /admin/, backend never serves code', async () => {
  edgeImpl = async () => edgeJson(401, {});
  const res = await worker.fetch(new Request('https://site.test/admin/pages/dashboard.html'), env());
  assert.equal(res.status, 302); assert.equal(res.headers.get('Location'), 'https://site.test/admin/');
});
test('dashboard pages: forged cookie -> redirect', async () => {
  edgeImpl = async () => edgeJson(401, { error: 'session expired' });
  const res = await worker.fetch(new Request('https://site.test/admin/pages/js/app.js', { headers: { Cookie: '__Host-badshah_admin=forged' } }), env());
  assert.equal(res.status, 302);
});
test('dashboard pages: valid session -> served, no-store', async () => {
  edgeImpl = async () => edgeJson(200, { ok: true });
  const res = await worker.fetch(new Request('https://site.test/admin/pages/dashboard.html', { headers: { Cookie: '__Host-badshah_admin=good' } }), env());
  assert.equal(res.status, 200); assert.equal(await res.text(), 'ASSET:/admin/pages/dashboard.html'); assert.equal(res.headers.get('Cache-Control'), 'no-store');
});
test('login page is public; /admin redirects to /admin/', async () => {
  edgeImpl = async () => { throw new Error('should not call backend'); };
  assert.equal((await worker.fetch(new Request('https://site.test/admin/'), env())).status, 200);
  assert.equal((await worker.fetch(new Request('https://site.test/admin'), env())).status, 301);
});
test('secret-looking files are never served', async () => {
  for (const p of ['/google-services.json', '/x/service-account.json', '/a.env', '/m.sql', '/k.jks', '/app.js.map'])
    assert.equal((await worker.fetch(new Request('https://site.test' + p), env())).status, 404, p);
});
test('backend down -> 502 not a crash', async () => {
  edgeImpl = async () => { throw new Error('down'); };
  assert.equal((await worker.fetch(api({ action: 'overview' }, { cookie: '__Host-badshah_admin=t' }), env())).status, 502);
});

:root{--bg:#0b0d14;--panel:#141824;--line:#262e45;--text:#e8ebf5;--mute:#8b94b3;--gold:#f5b942;--code:#0f1320}
@media (prefers-color-scheme:light){:root{--bg:#f4f5fa;--panel:#fff;--line:#dde1ee;--text:#171a26;--mute:#5d6685;--code:#eef0f8}}
*{box-sizing:border-box}html,body{margin:0;height:100%}body{font:15px/1.6 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--text);display:flex;flex-direction:column}
a{color:var(--gold)}.bar{display:flex;gap:12px;align-items:center;padding:10px 16px;background:var(--panel);border-bottom:1px solid var(--line);flex-wrap:wrap}
.bar img{border-radius:50%;border:1px solid var(--gold)}.sub{color:var(--mute);font-size:.85em;flex:1;min-width:120px}
#q{background:var(--code);border:1px solid var(--line);border-radius:10px;padding:.5em .8em;color:var(--text);min-width:240px;font:inherit}.adm{font-size:.85em}
.layout{display:grid;grid-template-columns:320px 1fr;flex:1;min-height:0}
#tree{border-right:1px solid var(--line);overflow:auto;padding:10px;background:var(--panel);font-size:.9em}
#viewer{overflow:auto;padding:24px 32px;min-width:0}
.node{list-style:none;margin:0;padding-left:16px}.node.root{padding-left:0}
.dir>button,.file>button{all:unset;cursor:pointer;display:block;width:100%;padding:3px 6px;border-radius:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dir>button:hover,.file>button:hover{background:var(--code)}.file>button.on{background:var(--code);color:var(--gold)}.file>button.nocontent{color:var(--mute)}
.dir>button::before{content:"\25B8  "}.dir.open>button::before{content:"\25BE  "}.dir:not(.open)>ul{display:none}
.file>button::before{content:"\2022  ";color:var(--mute)}
.crumb{color:var(--mute);font-size:.85em;margin-bottom:8px;word-break:break-all}
pre{background:var(--code);border:1px solid var(--line);border-radius:10px;padding:14px;overflow:auto;font-size:.85em;line-height:1.45}
code{background:var(--code);padding:.1em .35em;border-radius:5px;font-size:.92em}pre code{background:none;padding:0}
.md h1,.md h2,.md h3{line-height:1.25}.md h2{border-bottom:1px solid var(--line);padding-bottom:.2em;margin-top:1.6em}
.md table{border-collapse:collapse;display:block;overflow:auto}.md th,.md td{border:1px solid var(--line);padding:.4em .7em;text-align:left;vertical-align:top}
.md blockquote{border-left:3px solid var(--gold);margin:1em 0;padding:.1em 1em;color:var(--mute)}
.results{list-style:none;padding:0}.results li{border:1px solid var(--line);border-radius:10px;padding:10px 14px;margin:8px 0;background:var(--panel);cursor:pointer}
.results li:hover{border-color:var(--gold)}.results .p{font-weight:700}.results .s{color:var(--mute);font-size:.88em;margin-top:4px;white-space:pre-wrap;word-break:break-word}
mark{background:#f5b94255;color:inherit;border-radius:3px}.note{color:var(--mute)}
@media(max-width:800px){.layout{grid-template-columns:1fr}#tree{max-height:40vh;border-right:0;border-bottom:1px solid var(--line)}}

// Project explorer: expandable tree + full-text search + safe markdown viewer. No innerHTML anywhere.
const $ = (s) => document.querySelector(s);
const el = (t, a = {}, ...k) => { const e = document.createElement(t); for (const [x, v] of Object.entries(a)) { if (x === 'class') e.className = v; else if (x.startsWith('on')) e.addEventListener(x.slice(2), v); else if (v != null) e.setAttribute(x, v); } e.append(...k.flat().filter((n) => n != null)); return e; };
const viewer = $('#viewer'), treeEl = $('#tree');

const data = await (await fetch('files.json')).json();
const files = data.files, byPath = new Map(files.map((f) => [f.path, f]));

// ---- tree ----
const root = {};
for (const f of files) { let n = root; const parts = f.path.split('/'); parts.forEach((p, i) => { n.c ??= {}; n = n.c[p] ??= i === parts.length - 1 ? { file: f } : {}; }); }
function build(node, open) {
  const ul = el('ul', { class: 'node' + (open ? ' root' : '') });
  const names = Object.keys(node.c || {}).sort((a, b) => (!!node.c[b].c - !!node.c[a].c) || a.localeCompare(b));
  for (const name of names) {
    const ch = node.c[name];
    if (ch.file) {
      const b = el('button', { type: 'button', class: ch.file.content == null ? 'nocontent' : '', title: ch.file.path, onclick: () => openFile(ch.file.path) }, name);
      ul.append(el('li', { class: 'file', 'data-path': ch.file.path }, b));
    } else {
      const li = el('li', { class: 'dir' + (open ? ' open' : '') });
      li.append(el('button', { type: 'button', onclick: () => li.classList.toggle('open') }, name + '/'), build(ch));
      ul.append(li);
    }
  }
  return ul;
}
treeEl.append(build(root, true));
function revealInTree(p) {
  for (const b of treeEl.querySelectorAll('button.on')) b.classList.remove('on');
  const li = [...treeEl.querySelectorAll('li.file')].find((x) => x.dataset.path === p); if (!li) return;
  li.firstChild.classList.add('on'); for (let n = li.parentElement; n && n !== treeEl; n = n.parentElement) if (n.classList?.contains('dir')) n.classList.add('open');
  li.scrollIntoView({ block: 'nearest' });
}

// ---- markdown (safe subset) ----
function inline(text, parent) {
  const re = /(`[^`]+`)|(\*\*[^*]+\*\*)|(\[[^\]]+\]\([^)]+\))/g; let last = 0, m;
  while ((m = re.exec(text))) {
    parent.append(text.slice(last, m.index)); const t = m[0];
    if (t[0] === '`') parent.append(el('code', {}, t.slice(1, -1)));
    else if (t.startsWith('**')) parent.append(el('b', {}, t.slice(2, -2)));
    else { const [, label, href] = /\[([^\]]+)\]\(([^)]+)\)/.exec(t);
      if (/^https:\/\//.test(href)) parent.append(el('a', { href, rel: 'noopener noreferrer', target: '_blank' }, label));
      else { const target = resolve(href); parent.append(target ? el('a', { href: '#', onclick: (e) => { e.preventDefault(); openFile(target); } }, label) : label); } }
    last = m.index + t.length;
  }
  parent.append(text.slice(last));
}
let currentDir = '';
function resolve(href) { const p = href.split('#')[0]; if (!p) return null; const parts = (currentDir ? currentDir.split('/') : []).concat(p.split('/')); const out = []; for (const x of parts) { if (x === '..') out.pop(); else if (x !== '.') out.push(x); } const r = out.join('/'); return byPath.has(r) ? r : null; }
function markdown(src) {
  const box = el('div', { class: 'md' }); const lines = src.replace(/\r/g, '').split('\n'); let i = 0;
  while (i < lines.length) {
    const L = lines[i];
    if (/^```/.test(L)) { const buf = []; i++; while (i < lines.length && !/^```/.test(lines[i])) buf.push(lines[i++]); i++; box.append(el('pre', {}, el('code', {}, buf.join('\n')))); continue; }
    let m;
    if ((m = /^(#{1,4})\s+(.*)$/.exec(L))) { const h = el('h' + m[1].length); inline(m[2], h); box.append(h); i++; continue; }
    if (/^\|.*\|\s*$/.test(L) && /^\|[\s:|-]+\|\s*$/.test(lines[i + 1] || '')) {
      const rows = []; const head = L; i += 2; while (i < lines.length && /^\|.*\|\s*$/.test(lines[i])) rows.push(lines[i++]);
      const cells = (r) => r.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim());
      const t = el('table'), thead = el('thead', {}, el('tr', {}, cells(head).map((c) => { const th = el('th'); inline(c, th); return th; })));
      const tb = el('tbody'); for (const r of rows) tb.append(el('tr', {}, cells(r).map((c) => { const td = el('td'); inline(c, td); return td; }))); t.append(thead, tb); box.append(t); continue;
    }
    if (/^\s*([-*]|\d+\.)\s+/.test(L)) { const ord = /^\s*\d+\./.test(L), ul = el(ord ? 'ol' : 'ul'); while (i < lines.length && /^\s*([-*]|\d+\.)\s+/.test(lines[i])) { const li = el('li'); inline(lines[i].replace(/^\s*([-*]|\d+\.)\s+/, ''), li); ul.append(li); i++; } box.append(ul); continue; }
    if (/^>\s?/.test(L)) { const bq = el('blockquote'); const buf = []; while (i < lines.length && /^>\s?/.test(lines[i])) buf.push(lines[i++].replace(/^>\s?/, '')); const p = el('p'); inline(buf.join(' '), p); bq.append(p); box.append(bq); continue; }
    if (!L.trim()) { i++; continue; }
    const buf = []; while (i < lines.length && lines[i].trim() && !/^(#{1,4}\s|```|>|\s*([-*]|\d+\.)\s|\|)/.test(lines[i])) buf.push(lines[i++]);
    const p = el('p'); inline(buf.join(' '), p); box.append(p);
  }
  return box;
}

// ---- viewer ----
function openFile(p, push = true) {
  const f = byPath.get(p); if (!f) return;
  currentDir = p.includes('/') ? p.slice(0, p.lastIndexOf('/')) : '';
  viewer.replaceChildren(el('div', { class: 'crumb' }, p + '  -  ' + (f.size / 1024).toFixed(1) + ' KB'));
  if (f.content == null) viewer.append(el('p', { class: 'note' }, 'Not shown here (binary, secret-bearing, or larger than 80 KB). Open it in the source ZIP.'));
  else if (/\.md$/i.test(p)) viewer.append(markdown(f.content));
  else viewer.append(el('pre', {}, el('code', {}, f.content)));
  revealInTree(p); viewer.scrollTop = 0; if (push) history.replaceState(null, '', '#' + encodeURIComponent(p));
}

// ---- search ----
function snippet(content, q) {
  const i = content.toLowerCase().indexOf(q); if (i < 0) return null;
  const s = content.slice(Math.max(0, i - 60), i + q.length + 90).replace(/\s+/g, ' ');
  const j = s.toLowerCase().indexOf(q); return el('div', { class: 's' }, s.slice(0, j), el('mark', {}, s.slice(j, j + q.length)), s.slice(j + q.length));
}
function search(raw) {
  const q = raw.trim().toLowerCase(); if (q.length < 2) { return; }
  const hits = [];
  for (const f of files) {
    const nameHit = f.path.toLowerCase().includes(q), sn = f.content ? snippet(f.content, q) : null;
    if (nameHit || sn) hits.push({ f, sn, score: (nameHit ? 2 : 0) + (/^documentation\/|README/i.test(f.path) ? 1 : 0) });
  }
  hits.sort((a, b) => b.score - a.score);
  const ul = el('ul', { class: 'results' });
  for (const h of hits.slice(0, 60)) ul.append(el('li', { tabindex: 0, onclick: () => openFile(h.f.path), onkeydown: (e) => { if (e.key === 'Enter') openFile(h.f.path); } }, el('div', { class: 'p' }, h.f.path), h.sn));
  viewer.replaceChildren(el('h2', {}, `${hits.length} result${hits.length === 1 ? '' : 's'} for "${raw.trim()}"`), hits.length ? ul : el('p', { class: 'note' }, 'No matches.'));
}
let t; $('#q').addEventListener('input', (e) => { clearTimeout(t); t = setTimeout(() => (e.target.value.trim().length >= 2 ? search(e.target.value) : null), 200); });
const start = decodeURIComponent(location.hash.slice(1)); if (byPath.has(start)) openFile(start, false); else if (byPath.has('README.md')) openFile('README.md', false);

// Assembles ./website  =  docs explorer (/)  +  admin panel (/admin)  +  files.json
// Usage: node scripts/build-site.mjs
// The explorer data is SCRUBBED: secret-looking files are excluded, and the build
// FAILS if a private key / secret key pattern is found anywhere.
import fs from 'node:fs'; import path from 'node:path'; import { fileURLToPath } from 'node:url';
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(ROOT, 'website');
const EXCLUDE_DIR = new Set(['node_modules', '.git', 'build', '.gradle', 'website', 'dist', '.wrangler', '.idea', 'release-artifacts']);
const EXCLUDE_FILE = /(^|\/)(\.env.*|local\.properties|google-services\.json|.*\.(jks|keystore|p12|pem|key|apk|aab|zip)|.*service[-_]?account.*\.json|supabase-connection-details\.txt|keystore\.properties)$/i;
const TEXT = /\.(md|txt|sql|ts|tsx|js|mjs|json|toml|kts|kt|xml|html|css|yml|yaml|gradle|properties|pro|sh|svg)$/i;
const FATAL = [/-----BEGIN [A-Z ]*PRIVATE KEY-----/, /sb_secret_[A-Za-z0-9_-]{10,}/, /gh[pousr]_[A-Za-z0-9]{30,}/, /AKIA[0-9A-Z]{16}/, /eyJhbGciOi[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\./];
const MASK = [[/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '<email-redacted>'], [/AIza[0-9A-Za-z_-]{35}/g, '<public-client-key-redacted>'], [/sb_publishable_[A-Za-z0-9_-]+/g, '<supabase-publishable-key-redacted>']];
const MAX = 80_000;

function walk(dir, rel = '') {
  const out = [];
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const r = rel ? `${rel}/${e.name}` : e.name;
    if (e.isDirectory()) { if (!EXCLUDE_DIR.has(e.name)) out.push(...walk(path.join(dir, e.name), r)); }
    else if (!EXCLUDE_FILE.test(r)) out.push(r);
  }
  return out;
}
const files = [];
for (const rel of walk(ROOT).sort()) {
  const abs = path.join(ROOT, rel), size = fs.statSync(abs).size;
  const item = { path: rel, size };
  if (TEXT.test(rel) && size <= MAX) {
    let c = fs.readFileSync(abs, 'utf8');
    for (const re of FATAL) if (re.test(c)) { console.error(`BUILD FAILED: secret pattern ${re} in ${rel}`); process.exit(1); }
    for (const [re, rep] of MASK) c = c.replace(re, rep);
    item.content = c;
  }
  files.push(item);
}
fs.rmSync(OUT, { recursive: true, force: true });
fs.cpSync(path.join(ROOT, 'docs-site'), OUT, { recursive: true });
fs.cpSync(path.join(ROOT, 'admin-panel'), path.join(OUT, 'admin'), { recursive: true });
fs.rmSync(path.join(OUT, 'admin', 'README.md'), { force: true });
fs.mkdirSync(path.join(OUT, 'assets'), { recursive: true });
fs.copyFileSync(path.join(ROOT, 'admin-panel/assets/badshah-logo.webp'), path.join(OUT, 'assets/badshah-logo.webp'));
fs.writeFileSync(path.join(OUT, 'files.json'), JSON.stringify({ generated: new Date().toISOString(), files }));
console.log(`website built: ${files.length} files indexed (${files.filter((f) => f.content).length} with content)`);
